.forge-adobe-is-transforming-the-world-s-biggest-brands img, .forge-adobe-is-transforming-the-world-s-biggest-brands svg {max-width:100%;display:block}

.forge-adobe-is-transforming-the-world-s-biggest-brands {max-width:var(--max-width);margin-inline:auto;padding-inline:clamp(20px,5vw,48px)}

.forge-adobe-is-transforming-the-world-s-biggest-brands {font-weight:700;color:var(--color-accent);display:inline-flex;align-items:center;gap:6px}

.forge-adobe-is-transforming-the-world-s-biggest-brands:hover {color:var(--blue-deep)}

.forge-adobe-is-transforming-the-world-s-biggest-brands::after {content:"→";transition:transform 200ms var(--ease)}

.forge-adobe-is-transforming-the-world-s-biggest-brands:hover::after {transform:translateX(3px)}

.forge-adobe-is-transforming-the-world-s-biggest-brands {max-width:60ch;margin-bottom:40px}

.forge-adobe-is-transforming-the-world-s-biggest-brands h2 {font-size:var(--heading-xl)}

.forge-adobe-is-transforming-the-world-s-biggest-brands p {font-size:var(--body-lg);color:var(--ink-64);margin-top:16px}

.forge-adobe-is-transforming-the-world-s-biggest-brands .card .link-arrow {margin-top:20px}

.forge-adobe-is-transforming-the-world-s-biggest-brands {display:flex;flex-wrap:wrap;align-items:center;gap:clamp(28px,5vw,64px);padding:8px 0 40px;opacity:.85}

.forge-adobe-is-transforming-the-world-s-biggest-brands img {height:34px;width:auto;filter:grayscale(1);opacity:.7;transition:filter 200ms,opacity 200ms}

.forge-adobe-is-transforming-the-world-s-biggest-brands img:hover {filter:grayscale(0);opacity:1}

.forge-adobe-is-transforming-the-world-s-biggest-brands {display:grid;grid-template-columns:auto 1fr;gap:clamp(24px,4vw,56px);align-items:center;
  background:var(--warm-stone);border-radius:var(--radius);padding:clamp(28px,4vw,48px)}

.forge-adobe-is-transforming-the-world-s-biggest-brands img {height:40px}

.forge-adobe-is-transforming-the-world-s-biggest-brands blockquote {margin:0;font-family:var(--heading-font-family);font-weight:900;font-size:clamp(22px,2.4vw,32px);line-height:1.1;letter-spacing:-.015em}

.forge-adobe-is-transforming-the-world-s-biggest-brands {font-weight:700;font-size:var(--body-sm);color:var(--gray-700);margin:20px 0 16px}

.forge-adobe-is-transforming-the-world-s-biggest-brands .act-dark .section-head p {color:var(--paper-72)}

.forge-adobe-is-transforming-the-world-s-biggest-brands .news-card .link-arrow {color:var(--s2a-color-gray-25, #fff)}

.forge-adobe-is-transforming-the-world-s-biggest-brands .news-card .link-arrow:hover {color:var(--paper-72)}

@media (max-width:960px) {
.forge-adobe-is-transforming-the-world-s-biggest-brands {grid-template-columns:1fr}
}

@media (max-width:640px) {
.forge-adobe-is-transforming-the-world-s-biggest-brands {margin-top:12px}
}

